insert into public.catalog_items(id,item_type,title,description,details) select '10000000-0000-4000-8000-000000000001'::uuid,'product'::public.catalog_item_type,'Трубчатая фрикционная анкерная крепь','Стальной анкер с продольной прорезью. При установке в шпур закрепляется за счёт трения о породу.','{"specs": [{"label": "Исполнения", "value": "ТФА39 · ТФА40 · ТФА45 · ТФА46 · ТФА47 · ТФА48"}, {"label": "Длина", "value": "600–3000 мм"}, {"label": "Толщина стенки", "value": "2,5–3,0 мм"}], "variants": ["ТФА39", "ТФА40", "ТФА45", "ТФА46", "ТФА47", "ТФА48"], "length": true, "application": "Крепление кровли и бортов шахт и рудников, в том числе совместно с сеткой или армокаркасом. Другие длины — по согласованию.", "documents": []}'::jsonb where not exists(select 1 from public.catalog_items where title='Трубчатая фрикционная анкерная крепь') on conflict(id) do nothing;
insert into public.catalog_items(id,item_type,title,description,details) select '10000000-0000-4000-8000-000000000002'::uuid,'product'::public.catalog_item_type,'Опорные плиты','Передают усилие от анкера на поверхность породы, металлическую сетку или армокаркас.','{"specs": [{"label": "Размеры", "value": "150 × 150 · 200 × 200 · 250 × 250 мм"}, {"label": "Комплектация", "value": "Совместно с анкерной крепью ТФА"}], "variants": ["150 × 150 мм", "200 × 200 мм", "250 × 250 мм"], "length": false, "application": "Распределение нагрузки в системе крепления горных выработок.", "documents": []}'::jsonb where not exists(select 1 from public.catalog_items where title='Опорные плиты') on conflict(id) do nothing;
insert into public.catalog_items(id,item_type,title,description,details) select '10000000-0000-4000-8000-000000000003'::uuid,'product'::public.catalog_item_type,'Армокаркасы','Элементы системы крепления горных выработок для совместного применения с анкерами и опорными плитами.','{"specs": [], "variants": [], "length": false, "application": "Укажите требуемые размеры и условия применения в заявке — специалисты уточнят исполнение.", "documents": []}'::jsonb where not exists(select 1 from public.catalog_items where title='Армокаркасы') on conflict(id) do nothing;
insert into public.catalog_items(id,item_type,title,description,details) select '10000000-0000-4000-8000-000000000004'::uuid,'service'::public.catalog_item_type,'Производство анкерной крепи ТФА','Серийное изготовление трубчатой фрикционной анкерной крепи стандартных типоразмеров.','{"specs": [], "variants": [], "length": false, "application": "Результат: партия продукции с комплектом документов для крепления кровли и бортов горных выработок.", "documents": []}'::jsonb where not exists(select 1 from public.catalog_items where title='Производство анкерной крепи ТФА') on conflict(id) do nothing;
insert into public.catalog_items(id,item_type,title,description,details) select '10000000-0000-4000-8000-000000000005'::uuid,'service'::public.catalog_item_type,'Изготовление ТФА согласованной длины','Изготовление анкеров нужной длины в рамках требований технических условий.','{"specs": [], "variants": [], "length": false, "application": "Для проектов, где стандартные длины не подходят. Требуемые параметры укажите в заявке.", "documents": []}'::jsonb where not exists(select 1 from public.catalog_items where title='Изготовление ТФА согласованной длины') on conflict(id) do nothing;
insert into public.catalog_items(id,item_type,title,description,details) select '10000000-0000-4000-8000-000000000006'::uuid,'service'::public.catalog_item_type,'Комплектация опорными плитами','Поставка ТФА с опорными плитами предусмотренных типоразмеров.','{"specs": [], "variants": [], "length": false, "application": "Готовый комплект для монтажа анкерного крепления совместно с сеткой или армокаркасом.", "documents": []}'::jsonb where not exists(select 1 from public.catalog_items where title='Комплектация опорными плитами') on conflict(id) do nothing;
